import java.util.*;
class Stats { long count,sum,max; void add(long value){count++;sum+=value;max=Math.max(max,value);} }
public class Main { public static void main(String[] args){ Scanner s=new Scanner(System.in);int n=s.nextInt();Map<String,Stats> stats=new TreeMap<>();for(int i=0;i<n;i++){String endpoint=s.next();long latency=s.nextLong();stats.computeIfAbsent(endpoint,k->new Stats()).add(latency);}stats.forEach((endpoint,v)->System.out.println(endpoint+" count="+v.count+" avg="+(v.sum/v.count)+" max="+v.max));} }
